import{ROOMS,route,initial,act,time}from'./engine.mjs';
const $=id=>document.getElementById(id);let s=initial(),lastImage='',lastHistory=0,lastActions='',lastAt='',audio=null,muted=true;
const descriptions={ready:['A moment between things','You can linger. Or let familiarity take you home.'],idle:['Attention is elsewhere','A familiar intention waits beneath the surface.'],walking:['Following a familiar path','The journey continues. You can take control at any moment.'],paused:['You are here, consciously','The routine waits. Choose a step, or let the journey continue.'],blocked:['This needs your attention','The balcony passage is closed for cleaning. What will you do?'],home:['Home, for now','You have arrived. The world beyond continues.']};
function actionDefs(){switch(s.phase){case'ready':return[['begin','Let the journey unfold →','primary']];case'idle':return[['take','Stay with this moment','primary']];case'walking':return[['take','Take control','primary']];case'paused':return[['resume','Continue home →','primary'],['step','Choose just the next step','secondary']];case'blocked':return[['wait','Wait for the passage','primary'],['detour','Find the hostel stairs','secondary']];case'home':return[['reset','Replay the journey ↺','primary']];}}
function dispatch(type,value){s=act(s,type,value);render();}
function makeActions(container,defs,discord=false){container.replaceChildren();for(const[type,label,cls]of defs){const b=document.createElement('button');b.textContent=label;b.className=discord?'':cls;b.addEventListener('click',()=>dispatch(type));container.append(b);}}
function render(){const r=ROOMS[s.at],[label,desc]=descriptions[s.phase];$('roomName').textContent=r.name;$('roomChapter').textContent=r.chapter.toUpperCase();$('roomText').textContent=r.text;$('storyClock').textContent=time(s.clock);$('elapsedLabel').textContent=s.clock===21*60+8?'No time has passed':`${s.clock-(21*60+8)} story minutes have passed`;$('phaseLabel').textContent=label;$('phaseText').textContent=s.phase==='idle'?`${Math.ceil(s.idle)} preview seconds before the routine begins.`:desc;$('statusDot').classList.toggle('active',['walking','idle'].includes(s.phase));$('timingNote').textContent=s.phase==='walking'?`Next scene in ${Math.max(1,Math.ceil(s.pace-s.elapsed))}s · ten story minutes per step`:s.phase==='blocked'?'Familiarity is useful. This choice is yours.':s.phase==='home'?'Routine has brought you here. What happens next is open.':'Observation leaves the routine undisturbed in this study.';
if(lastImage!==r.image){$('sceneImage').src=`assets/${r.image}.webp`;$('sceneImage').alt=r.name+' — Future Sky scene';$('discordImage').src=`assets/${r.image}.webp`;$('discordImage').alt=r.name;lastImage=r.image;}
const path=route(s.at,s.home,s.avoid),signature=s.at+'|'+s.home+'|'+s.avoid;
if(signature!==lastAt){const el=$('routeList');el.replaceChildren();path.forEach((node,i)=>{const d=document.createElement('div');d.className='route-point'+(i===0?' current':'');d.append(document.createTextNode(ROOMS[node].name));if(i===0){const sm=document.createElement('small');sm.textContent='YOU ARE HERE';d.append(sm);}else if(i===path.length-1){const sm=document.createElement('small');sm.textContent='HOME';d.append(sm);}el.append(d);});lastAt=signature;}
const defs=actionDefs(),sig=JSON.stringify(defs);if(sig!==lastActions){makeActions($('actionArea'),defs);makeActions($('discordActions'),defs,true);lastActions=sig;}
const h=s.history.at(-1);$('lastEvent').textContent=h.text;$('eventKind').textContent=({habitual:'FAMILIAR MOVEMENT',directed:'CONSCIOUS CHOICE',observation:'A MOMENT NOTICED',scene:'HERE, NOW'})[h.actor];$('historyCount').textContent=String(s.history.length).padStart(2,'0');if(lastHistory!==s.history.length){$('journalEntries').replaceChildren();[...s.history].reverse().forEach(e=>{const li=document.createElement('li'),tm=document.createElement('time'),div=document.createElement('div'),sm=document.createElement('small');tm.textContent=time(e.clock);div.textContent=e.text;sm.textContent=e.actor;div.append(sm);li.append(tm,div);$('journalEntries').append(li);});lastHistory=s.history.length;}
$('worldView').hidden=s.view!=='web';$('discordStudy').hidden=s.view!=='discord';for(const[id,v]of[['webView','web'],['discordView','discord']]){$(id).classList.toggle('selected',s.view===v);$(id).setAttribute('aria-pressed',s.view===v);}$('discordTime').textContent=time(s.clock);$('discordPhase').textContent=label.toUpperCase();$('discordRoom').textContent=r.name;$('discordText').textContent=s.phase==='blocked'?desc:r.text;$('discordProgress').textContent=s.phase==='idle'?`Your attention drifts · ${Math.ceil(s.idle)}s`:s.phase==='home'?`Arrived at ${ROOMS[s.home].name} · ${time(s.clock)}`:`Home: ${ROOMS[s.home].name} · ${path.length-1} steps remain`;$('pace').value=s.pace;$('homeTarget').value=s.home;$('obstacle').checked=s.obstacle;
}
$('webView').onclick=()=>dispatch('view','web');$('discordView').onclick=()=>dispatch('view','discord');$('backToWorld').onclick=()=>dispatch('view','web');$('observeButton').onclick=()=>dispatch('observe');$('resetButton').onclick=()=>dispatch('reset');$('homeTarget').onchange=e=>dispatch('home',e.target.value);$('pace').onchange=e=>dispatch('pace',e.target.value);$('obstacle').onchange=e=>dispatch('obstacle',e.target.checked);
for(const[button,dialog]of[['journalButton','journal'],['settingsButton','settings'],['aboutButton','about']])$(button).onclick=()=>$(dialog).showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('soundButton').onclick=async()=>{try{if(!audio){const ctx=new(window.AudioContext||window.webkitAudioContext)(),gain=ctx.createGain();gain.gain.value=.018;gain.connect(ctx.destination);[73.416,110,146.832].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=f;o.detune.value=i*3;g.gain.value=.6;o.connect(g);g.connect(gain);o.start();});audio=ctx;}muted=!muted;if(muted)await audio.suspend();else await audio.resume();$('soundButton').textContent=muted?'♫  Sound off':'♫  Sound on';$('soundButton').setAttribute('aria-pressed',!muted);}catch{$('soundButton').textContent='Sound unavailable';}};
let last=performance.now();setInterval(()=>{const now=performance.now(),dt=Math.min(.5,(now-last)/1000);last=now;if(!document.hidden){s=act(s,'tick',dt);render();}},200);render();
